package com.miniappplatform.nativehost
import org.junit.Assert.*
import org.junit.Test
import java.util.Calendar
class DomainTests {
    private val weather = MiniApp("weather", "Thời tiết", "Thời tiết", listOf("/", "/forecast/:day"), "/", listOf(Entry("forecast", "/", listOf("transit", "host_notification"), listOf("area"))), listOf(Link("open_transit", "Giao thông", "transit", "nearby", listOf("area"))))
    private val transit = MiniApp("transit", "Giao thông", "Giao thông", listOf("/"), "/", listOf(Entry("nearby", "/", listOf("weather"), listOf("area"))), emptyList())
    private val catalog = Catalog(listOf(weather, transit), listOf(Tenant("vn-hn", "Hà Nội", "", listOf("weather", "transit"), "", 21.0285, 105.8542), Tenant("vn-fallback", "Toàn quốc", "", listOf("weather"), "", 16.0, 108.0)), emptyList(), emptyList(), emptyList(), emptyList(), 250, 3_600_000)
    private fun slot(owner: String? = null, people: List<Person> = emptyList()) = Slot("x", "tomorrow", "Sân 1", "CLB", "18:00", "19:00", 120000, 4, owner, "open", people)
    @Test fun searchAndTenant() { assertTrue(matches("Ưu đãi ăn uống", "uu dai uong")); assertFalse(matches("ăn uống", "uống sân")); assertEquals("vn-hn", catalog.resolve(21.0285, 105.8542)); assertEquals("vn-fallback", catalog.resolve(Double.NaN, 0.0)) }
    @Test fun routesAndBack() { val n = Navigator(); assertTrue(n.open("weather", catalog, "vn-hn")); for (p in listOf("https://evil.com", "//evil", "/%2e%2e", "/forecast/%2fsecret", "/unknown", "/forecast/%ZZ")) assertFalse(p, Routes.allows(p, weather)); assertTrue(n.navigate("/forecast/tomorrow", catalog)); n.back(); assertEquals("/", n.frames.last().path); assertTrue(n.cross("open_transit", catalog, "vn-hn")); assertEquals(2, n.frames.size); n.back(); assertEquals("weather", n.frames.last().app); assertFalse(n.open("transit", catalog, "vn-fallback")) }
    @Test fun notificationBoundary() { val n = Navigator(); assertFalse(n.notification(InboxItem("x", "", "", 0, app = "weather", entry = "forecast", input = mapOf("token" to "bad")), catalog, "vn-hn")); assertFalse(n.notification(InboxItem("x", "", "", 0, expires = 1, app = "weather", entry = "forecast"), catalog, "vn-hn")); assertTrue(n.notification(InboxItem("x", "", "", 0, app = "weather", entry = "forecast", input = mapOf("area" to "current")), catalog, "vn-hn")) }
    @Test fun bookingOwnershipCapacityAndIdempotency() { val booked = slot().book(true).book(false); assertEquals("open", booked.visibility); assertTrue(booked.remove("me").includesMe); assertNull(booked.cancel().owner); val full = slot("other", (1..4).map { Person("p$it", "p") }); assertEquals(full, full.join()); assertEquals(full, full.cancel()); val joined = slot("other", listOf(Person("a", "A"))).join().join(); assertEquals(2, joined.people.size) }
    @Test fun preferenceNormalization() { val p = Preferences(apps = listOf("weather", "weather", "evil"), dock = listOf("weather", "weather")).normalized(catalog, "vn-hn"); assertEquals(listOf("weather"), p.apps); assertEquals(listOf("weather", ""), p.dock) }
    @Test fun intervalIsLocalAndOvernight() { val now = Calendar.getInstance().apply { set(2026, Calendar.OCTOBER, 3, 20, 0, 0); set(Calendar.MILLISECOND, 0) }; val interval = slot().copy(date = "weekend", start = "18:00", end = "01:00").interval(now)!!; assertTrue(interval.first > now.timeInMillis); assertEquals(7 * 60 * 60_000L, interval.second - interval.first) }
    @Test fun bridgeGatesQuotaRevokeAndAudit() { val broker = PreviewBroker(listOf(Capability("storage.kv", 1, "low", "none", "sandbox", 65536, 120, 20), Capability("ai.extract_bill", 1, "high", "once", "first_party", 8192, 4, 2))); val a = PreviewSession.sample("vn-hn"); val b = PreviewSession.sample("vn-hcm"); assertNull(broker.call(a, "storage.kv", "set", mapOf("key" to "x", "value" to "synthetic"), now = 0).error); assertNull(broker.call(b, "storage.kv", "get", mapOf("key" to "x"), now = 0).data["value"]); assertEquals(BridgeCode.INVALID_ARGUMENT, broker.call(a, "storage.kv", "get", mapOf("key" to "x", "appId" to "b"), now = 0).error); assertEquals(BridgeCode.CONSENT_REQUIRED, broker.call(a, "ai.extract_bill", "extract", mapOf("locale" to "vi", "idempotencyKey" to "test")).error); assertEquals(BridgeCode.UNAVAILABLE, broker.call(a, "ai.extract_bill", "extract", mapOf("locale" to "vi", "idempotencyKey" to "test"), consent = true).error); repeat(25) { broker.call(a, "storage.kv", "get", mapOf("key" to "x"), now = 0) }; assertEquals(BridgeCode.RATE_LIMITED, broker.audit.last().error); broker.revoke(a); assertEquals(BridgeCode.REVOKED, broker.call(a, "storage.kv", "get", mapOf("key" to "x")).error); assertFalse(broker.audit.last().digest.contains("synthetic")); assertEquals(broker.audit.elementAt(broker.audit.size - 2).hash, broker.audit.last().previousHash) }
}
